const { World } = require('miniplex');
const seedrandom = require('seedrandom');
const { Identity, Location, Political } = require('./src/components');
const { simulateHistory } = require('./src/history');
const { determineBiome } = require('./src/biomes');

// Mock db module
jest.mock('./src/db', () => ({
    saveDelta: jest.fn()
}));

const world = new World();

// Generate a town with political component
const townEntity = world.add({
    identity: Identity('Test City', 'Town', 'test-town-id'),
    location: Location(10, 20),
    history: { events: [] },
    currentMayor: 'NPC',
    political: Political(1, {}),
    population: 0
});

console.log('Initial town state:', {
    name: townEntity.identity.name,
    tier: townEntity.political.tier,
    population: townEntity.population
});

// Simulate 200 years with good population growth (roughly 10+ NPCs per decade)
const rng = seedrandom('test-settlement');
simulateHistory(world, rng, 10, 20, 200, 1);

console.log('\nAfter 200 years of simulation:');
console.log('Final town state:', {
    name: townEntity.identity.name,
    tier: townEntity.political.tier,
    population: townEntity.population,
    history: townEntity.history.events.filter(e => e.includes('grown to a')).length
});

console.log('\nPromotion events:');
townEntity.history.events
    .filter(e => e.includes('grown to a'))
    .forEach(e => console.log('-', e));

// Verify settlements grow
if (townEntity.political.tier > 1) {
    console.log('\n✓ SUCCESS: Settlement promoted from tier 1 to tier', townEntity.political.tier);
} else {
    console.log('\n✗ FAIL: Settlement did not promote');
}
EOF
