cd /Users/fernando.doglio/workspace/generator && node -e "
const { loadCoordinate, serializeChunk, unloadCoordinate } = require('./index.js');
const { generateMiniMap } = require('./src/map.js');

console.log('=== SCENARIO: Load, simulate, unload, then check map ===');
console.log('');

// Step 1: Load the coordinate and let it simulate
console.log('Step 1: Loading (0, 0)...');
loadCoordinate(0, 0);

// Step 2: Serialize to see the town state
const loaded = serializeChunk(0, 0);
console.log('Step 2: Town after loading:');
console.log('  - Name:', loaded.town.name);
console.log('  - Ruler:', loaded.town.ruler);
console.log('  - Tier:', loaded.town.tier);
console.log('  - Population:', loaded.town.population);
console.log('');

// Step 3: Unload (which saves deltas)
console.log('Step 3: Unloading (0, 0)...');
unloadCoordinate(0, 0);
console.log('');

// Step 4: Check the mini-map (which only queries deltas)
console.log('Step 4: Checking mini-map after unload:');
const miniMap = generateMiniMap(0, 0, 1);
console.log('  - Name:', miniMap.center.townName);
console.log('  - Ruler:', miniMap.center.ruler);
console.log('  - Tier:', miniMap.center.tier);
console.log('  - Settlement Type:', miniMap.center.settlementType);
console.log('  - Territory Radius:', miniMap.center.territoryRadius);
" 2>&1 | grep -v "LOG"

